<template><div class="attendance-pwa"><PwaPageHeader icon="fas fa-business-time" title="Laporan Lembur" subtitle="Rekap lembur yang disetujui" /><div class="toolbar"><input v-model="filters.bulan" type="month" class="form-control form-control-sm"><button class="btn btn-primary btn-sm" @click="loadData"><i class="fas fa-search"></i></button><button class="btn btn-outline-success btn-sm" @click="exportFile('excel')">XLSX</button><button class="btn btn-outline-danger btn-sm" @click="exportFile('pdf')">PDF</button></div><div class="total"><span>Total Lembur</span><strong>{{grandTotal.toFixed(2)}} jam</strong><small>{{monthLabel}}</small></div><div v-if="loading" class="empty">Memuat laporan...</div><div v-else-if="!rows.length" class="empty">Tidak ada lembur.</div><div v-else class="employees"><button v-for="r in rows" :key="r.pegawai_id||r.nip" type="button" class="employee" @click="openDetail(r)"><div class="employee-top"><div><strong>{{r.nama}}</strong><small>{{r.nip}} · {{r.jabatan||'-'}}</small></div><b>{{Number(r.total_jam||0).toFixed(2)}} jam</b></div><div class="strip"><span v-for="d in days" :key="d" :class="['dot',{'has':Number(r.harian?.[d]||0)>0}]">{{Number(r.harian?.[d]||0)>0?Number(r.harian[d]).toFixed(1):''}}</span></div></button></div><div v-if="detailOpen" class="modal-bg" @click.self="closeDetail"><section class="sheet"><div class="handle"></div><div class="sheet-head"><div><span>Detail Lembur</span><h6>{{selectedEmployee?.nama||'-'}}</h6></div><button @click="closeDetail"><i class="fas fa-times"></i></button></div><div v-if="detailLoading" class="empty">Memuat detail...</div><div v-else class="detail"><div class="detail-box"><span>Total</span><strong>{{Number(detailData?.total_jam||0).toFixed(2)}} jam</strong></div><div v-for="x in detailData?.lembur||[]" :key="x.id" class="detail-item"><strong>{{formatDate(x.tanggal)}}</strong><span>{{formatTime(x.jam_mulai)}} - {{formatTime(x.jam_selesai)}}</span><small>{{(Number(x.total_menit||0)/60).toFixed(2)}} jam · {{x.keterangan||'-'}}</small></div><div v-if="!detailData?.lembur?.length" class="empty">Tidak ada detail.</div></div></section></div></div></template>
<script setup>import PwaPageHeader from '../../../components/PwaPageHeader.vue';defineProps({filters:{type:Object,required:true},loading:Boolean,exporting:Boolean,rows:{type:Array,default:()=>[]},days:{type:Array,default:()=>[]},dailyTotals:{type:Object,default:()=>({})},grandTotal:{type:Number,default:0},detailOpen:Boolean,detailLoading:Boolean,selectedEmployee:{type:Object,default:null},detailData:{type:Object,default:null},monthLabel:{type:String,default:''},formatDate:{type:Function,required:true},formatTime:{type:Function,required:true},loadData:{type:Function,required:true},openDetail:{type:Function,required:true},closeDetail:{type:Function,required:true},exportFile:{type:Function,required:true}})</script>
